WITH activity AS (SELECT person_id AS person,toStartOfWeek(timestamp,1) AS week FROM events WHERE (event IN ('studio_screen_viewed','native_app_opened','native_screen_viewed','native_app_active','native_project_created','native_media_imported','native_export_completed','native_action_finished') OR event='product_action_completed') AND (properties.environment = 'production' AND properties.product = 'studio') GROUP BY person,week), cohorts AS (SELECT person_id AS person,toStartOfWeek(timestamp,1) AS week FROM events WHERE (event IN ('studio_screen_viewed','native_app_opened','native_screen_viewed','native_app_active','native_project_created','native_media_imported','native_export_completed','native_action_finished') OR event='product_action_completed') AND (properties.environment = 'production' AND properties.product = 'studio') AND {filters} GROUP BY person,week), joined AS (SELECT c.week AS week,c.person AS person,countIf(a.week=c.week+INTERVAL 7 DAY) AS returned FROM cohorts c LEFT JOIN activity a ON c.person=a.person WHERE c.week+INTERVAL 14 DAY<=now() GROUP BY c.week,c.person) SELECT week AS Week,count() AS Active,countIf(returned>0) AS Returned,round(100.0*countIf(returned>0)/nullIf(count(),0),1) AS Percent FROM joined GROUP BY Week ORDER BY Week LIMIT 100
